#include <cstdint>
#include <iostream>
#include <numeric>
#include <vector>
// 各成分の全頂点を小さい側から移し、絶対ポテンシャルを一括でずらす独立参照。
int main() {
    std::ios::sync_with_stdio(false); std::cin.tie(nullptr);
    constexpr int mod = 998244353;
    int n,q; if (!(std::cin>>n>>q)) return 0;
    std::vector<int> owner(n), value(n,0);
    std::iota(owner.begin(),owner.end(),0);
    std::vector<std::vector<int>> members(n);
    for (int i=0;i<n;++i) members[i].push_back(i);
    const auto norm = [](std::int64_t v) { v %= mod; if (v<0) v += mod; return static_cast<int>(v); };
    while (q--) {
        int type,u,v; std::cin>>type>>u>>v;
        int a=owner[u], b=owner[v];
        if (type==1) { std::cout<<(a==b ? norm(value[u]-value[v]) : -1)<<'\n'; continue; }
        int x; std::cin>>x;
        if (a==b) { std::cout<<(norm(value[u]-value[v])==x)<<'\n'; continue; }
        int shift=norm(static_cast<std::int64_t>(x)+value[v]-value[u]);
        if (members[a].size()>members[b].size()) { std::swap(a,b); shift=norm(-shift); }
        for (const int w:members[a]) { value[w]=norm(value[w]+shift); owner[w]=b; members[b].push_back(w); }
        std::vector<int>{}.swap(members[a]);
        std::cout<<1<<'\n';
    }
}

